"use strict";

// repo-memory export <claude|cursor|agents|all> [--check]
//
// Delivery is the agent tool's job; the records stay the source of truth. Each
// exporter writes generated files that load the right record when an agent touches
// matching files, and `--check` fails CI when those files drift from the records.
//
// Generated files carry a marker; only files with the marker are ever deleted, so a
// hand-written rule in the same folder is never touched.

const fs = require("fs");
const path = require("path");
const { loadRecords, LIVE } = require("../records");
const { health, isBroken } = require("../health");
const { renderForAgent, table } = require("../render");
const { UsageError } = require("../errors");

const MARKER = "generated by repo-memory";
const CLAUDE_DIR = ".claude/rules/repo-memory";
const CURSOR_DIR = ".cursor/rules/repo-memory";
const AGENTS_FILE = "AGENTS.md";
const BLOCK_START = "<!-- repo-memory:start -->";
const BLOCK_END = "<!-- repo-memory:end -->";
const CLI = "npx @semeton/repo-memory";

function liveRecords(ctx) {
  const { repo, config } = ctx;
  const { records } = loadRecords(repo, config);
  return records
    .filter((r) => LIVE.includes(r.status) && typeof r.id === "string" && r.scope.length)
    .map((r) => ({ record: r, health: health(r, repo, config) }));
}

function yamlString(s) {
  return JSON.stringify(String(s));
}

function claudeFiles(ctx, items) {
  const files = {};
  for (const { record: r, health: h } of items) {
    const front = `---\npaths:\n${r.scope.map((g) => `  - ${yamlString(g)}`).join("\n")}\n---\n`;
    const note = `<!-- ${MARKER} from ${r.file}; edit the record, not this file -->\n`;
    files[`${CLAUDE_DIR}/${r.id}.md`] = front + note + renderForAgent(r, h, { heading: "#" });
  }
  return { files, managedDirs: [CLAUDE_DIR] };
}

function cursorFiles(ctx, items) {
  const files = {};
  for (const { record: r, health: h } of items) {
    const front = `---\ndescription: ${yamlString(`${r.id}: ${r.title}`)}\nglobs: ${r.scope.join(",")}\nalwaysApply: false\n---\n`;
    const note = `<!-- ${MARKER} from ${r.file}; edit the record, not this file -->\n`;
    files[`${CURSOR_DIR}/${r.id}.mdc`] = front + note + renderForAgent(r, h, { heading: "#" });
  }
  return { files, managedDirs: [CURSOR_DIR] };
}

// AGENTS.md gets an index, not the records: a short table that tells an agent which
// records exist and how to fetch the ones that apply. Full text in an always-loaded
// file is the kind of context that measurably hurts agents.
function agentsBlock(ctx, items) {
  const { config } = ctx;
  const accepted = items.filter((x) => x.record.status === "accepted");
  const rejected = items.filter((x) => x.record.status === "rejected");
  const flag = (h) => (isBroken(h) ? " ⚠ evidence broken: verify before relying on it" : "");
  const lines = [
    BLOCK_START,
    `<!-- ${MARKER}: run \`${CLI} export agents\` after changing records in ${config.dir}/ -->`,
    "## Repository memory",
    "",
    `Team decisions that the code can't explain live in \`${config.dir}/\`. Before you change files, run \`${CLI} for <path>...\` for the files you will touch, and follow what it returns. To record something new, propose it with \`${CLI} propose\`; only a human can accept it.`,
    "",
  ];
  if (accepted.length) {
    lines.push(table(accepted.map(({ record: r, health: h }) => [r.scope.map((g) => `\`${g}\``).join(" "), r.id, r.title + flag(h)]), ["Applies to", "Record", "Title"]));
  } else {
    lines.push("No accepted records yet.");
  }
  if (rejected.length) {
    lines.push("", "Rejected proposals (don't reintroduce or propose again):", "");
    lines.push(table(rejected.map(({ record: r }) => [r.id, r.title]), ["Record", "Title"]));
  }
  lines.push(BLOCK_END);
  return lines.join("\n");
}

function agentsFiles(ctx, items) {
  const { repo } = ctx;
  const block = agentsBlock(ctx, items);
  const current = repo.exists(AGENTS_FILE) ? fs.readFileSync(repo.abs(AGENTS_FILE), "utf8") : null;
  let next;
  if (current === null) next = `# AGENTS.md\n\n${block}\n`;
  else {
    const s = current.indexOf(BLOCK_START);
    const e = current.indexOf(BLOCK_END);
    if (s !== -1 && e > s) next = current.slice(0, s) + block + current.slice(e + BLOCK_END.length);
    else if (s !== -1 || e !== -1) throw new UsageError(`${AGENTS_FILE} has an unmatched repo-memory marker; fix it by hand`);
    else next = `${current.replace(/\s*$/, "")}\n\n${block}\n`;
  }
  return { files: { [AGENTS_FILE]: next }, managedDirs: [] };
}

const TARGETS = { claude: claudeFiles, cursor: cursorFiles, agents: agentsFiles };

// Generated files on disk that the new plan no longer produces.
function orphans(repo, managedDirs, planned) {
  const out = [];
  for (const dir of managedDirs) {
    const abs = repo.abs(dir);
    if (!fs.existsSync(abs)) continue;
    for (const name of fs.readdirSync(abs)) {
      const rel = `${dir}/${name}`;
      if (planned[rel] !== undefined) continue;
      const text = repo.read(rel);
      if (text && text.includes(MARKER)) out.push(rel);
    }
  }
  return out;
}

function exportCommand({ ctx, args, flags, out, err }) {
  const target = args[0];
  const names = target === "all" ? Object.keys(TARGETS) : [target];
  if (!target || names.some((n) => !TARGETS[n])) throw new UsageError("usage: repo-memory export <claude|cursor|agents|all> [--check]");
  const { repo } = ctx;
  const items = liveRecords(ctx);

  const planned = {};
  const managed = [];
  for (const n of names) {
    const { files, managedDirs } = TARGETS[n](ctx, items);
    Object.assign(planned, files);
    managed.push(...managedDirs);
  }
  const remove = orphans(repo, managed, planned);
  const changed = Object.entries(planned).filter(([rel, content]) => repo.read(rel) !== content).map(([rel]) => rel);

  if (flags.check) {
    if (!changed.length && !remove.length) {
      out(`export ${target}: up to date (${Object.keys(planned).length} file${Object.keys(planned).length === 1 ? "" : "s"})`);
      return 0;
    }
    err(`export ${target}: out of date. Run \`repo-memory export ${target}\` and commit the result.`);
    for (const f of changed) err(`  changed  ${f}`);
    for (const f of remove) err(`  removed  ${f}`);
    return 1;
  }

  for (const rel of changed) {
    fs.mkdirSync(path.dirname(repo.abs(rel)), { recursive: true });
    fs.writeFileSync(repo.abs(rel), planned[rel]);
  }
  for (const rel of remove) fs.unlinkSync(repo.abs(rel));
  out(`export ${target}: ${changed.length} written, ${remove.length} removed, ${Object.keys(planned).length - changed.length} unchanged`);
  return 0;
}

module.exports = { exportCommand, agentsBlock, MARKER, CLAUDE_DIR, CURSOR_DIR, AGENTS_FILE };
